import { rm, access } from 'node:fs/promises';
import { rmSync } from 'node:fs';
import { pipeline } from 'node:stream/promises';
import { AppError } from '@crew/shared';
import { getIssue, validateIssueReferences } from './issues.js';
import { attachmentName, expectedHash, blobPath, receiveAttachment, attachmentStream } from './attachment-storage.js';
export function publicAttachment(row) {
  return { id: row.id, projectId: row.project_id, issueId: row.issue_id, name: row.name,
    mediaType: row.media_type, size: row.size, sha256: row.sha256, createdBy: row.created_by, createdAt: row.created_at,
    downloadUrl: '/api/v1/attachments/' + row.id + '/download' };
}
export function registerAttachments(ctx) {
  const { app, db, requireAuth, permissions, asyncRoute } = ctx;
  function issue(req, permission = 'project:read') {
    const value = getIssue(ctx, req.params.issueId);
    permissions.assertProject(req, value.projectId, permission);
    return value;
  }
  function attachment(req, permission = 'project:read') {
    const row = db.prepare('SELECT * FROM attachments WHERE id=?').get(req.params.attachmentId);
    if (!row) throw new AppError('NOT_FOUND', 'Attachment not found', 404);
    permissions.assertProject(req, row.project_id, permission);
    return row;
  }
  function emit(actorId, orgId, row, action) {
    const value = publicAttachment(row);
    ctx.bus.emit({ actorId, orgId, projectId: row.project_id, entityType: 'attachment', entityId: row.id,
      action, before: action === 'deleted' ? value : null, after: action === 'created' ? value : null, time: ctx.now() });
  }
  app.get('/api/v1/issues/:issueId/attachments', requireAuth, (req, res) => {
    const value = issue(req);
    const rows = db.prepare('SELECT * FROM attachments WHERE issue_id=? ORDER BY created_at,id').all(value.id);
    res.json({ ...ctx.paginate(rows.map(publicAttachment), req.query), maxUploadBytes: ctx.config.maxUploadBytes });
  });
  app.post('/api/v1/issues/:issueId/attachments', requireAuth, asyncRoute(async (req, res) => {
    const value = issue(req, 'attachment:write'); validateIssueReferences(ctx, value.projectId, {});
    const name = attachmentName(req.query.name ?? req.get('x-file-name'));
    const shaExpectation = expectedHash(req.get('x-content-sha256'));
    const mediaType = String(req.get('content-type') ?? 'application/octet-stream').slice(0, 255);
    if (mediaType.includes('application/json')) throw new AppError('VALIDATION', 'Send raw attachment bytes with application/octet-stream', 422, { contentType: 'JSON bodies are not attachment streams' });
    const id = ctx.id();
    const stored = await receiveAttachment(req, ctx.config, id, shaExpectation);
    let row;
    try {
      validateIssueReferences(ctx, value.projectId, {});
      getIssue(ctx, value.id);
      const time = ctx.now();
      db.prepare('INSERT INTO attachments VALUES (?,?,?,?,?,?,?,?,?)').run(id, value.projectId, value.id, name, mediaType, stored.size, stored.sha256, req.user.id, time);
      row = db.prepare('SELECT * FROM attachments WHERE id=?').get(id);
    } catch (error) { await rm(stored.target, { force: true }); throw error; }
    emit(req.user.id, value.orgId, row, 'created');
    res.status(201).json({ attachment: publicAttachment(row) });
  }));
  app.get('/api/v1/attachments/:attachmentId', requireAuth, (req, res) => res.json({ attachment: publicAttachment(attachment(req)) }));
  app.get('/api/v1/attachments/:attachmentId/download', requireAuth, asyncRoute(async (req, res) => {
    const row = attachment(req);
    try { await access(blobPath(ctx.config, row.id)); }
    catch (error) { if (error.code === 'ENOENT') throw new AppError('NOT_FOUND', 'Attachment bytes are unavailable', 404); throw error; }
    res.set({ 'Content-Type': 'application/octet-stream', 'Content-Length': String(row.size),
      'Content-Disposition': "attachment; filename*=UTF-8''" + encodeURIComponent(row.name),
      'X-Content-SHA256': row.sha256, ETag: '"sha256-' + row.sha256 + '"', 'Cache-Control': 'private, no-store' });
    try { await pipeline(attachmentStream(ctx.config, row.id), res); }
    catch (error) {
      if (!(['ERR_STREAM_PREMATURE_CLOSE', 'ECONNRESET'].includes(error.code) && res.destroyed)) throw error;
    }
  }));
  app.delete('/api/v1/attachments/:attachmentId', requireAuth, asyncRoute(async (req, res) => {
    const row = attachment(req, 'attachment:write');
    const project = permissions.assertProject(req, row.project_id, 'attachment:write');
    validateIssueReferences(ctx, project.id, {});
    await rm(blobPath(ctx.config, row.id), { force: true });
    db.prepare('DELETE FROM attachments WHERE id=?').run(row.id);
    emit(req.user.id, project.org_id, row, 'deleted'); res.json({ ok: true });
  }));
  const unsubscribe = ctx.bus.subscribe(event => {
    if (event.action !== 'deleted' || !['issue', 'project'].includes(event.entityType)) return;
    const column = event.entityType === 'issue' ? 'issue_id' : 'project_id';
    const rows = db.prepare('SELECT * FROM attachments WHERE ' + column + '=?').all(event.entityId);
    for (const row of rows) {
      rmSync(blobPath(ctx.config, row.id), { force: true });
      db.prepare('DELETE FROM attachments WHERE id=?').run(row.id);
      emit(event.actorId, event.orgId, row, 'deleted');
    }
  });
  (ctx.cleanups ??= []).push(unsubscribe);
}

import { test, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { testServer } from './helpers.js';
let server, owner, guest, org, project, issue, sprint;
beforeEach(async () => {
  server = await testServer(); owner = server.agent(); guest = server.agent();
  await owner('POST', '/auth/signup', { name: 'Planner', email: 'planner@sprint.test', password: 'correct-horse-123' });
  const guestId = (await guest('POST', '/auth/signup', { name: 'Guest', email: 'guest@sprint.test', password: 'correct-horse-123' })).data.user.id;
  org = (await owner('POST', '/orgs', { name: 'Sprint Org' })).data.organization;
  await owner('POST', '/orgs/' + org.id + '/members', { userId: guestId, role: 'guest' });
  project = (await owner('POST', '/orgs/' + org.id + '/projects', { key: 'SP', name: 'Sprint' })).data.project;
  await owner('POST', '/projects/' + project.id + '/guests', { userId: guestId });
  const today = new Date();
  const day = offset => new Date(today.valueOf() + offset * 86400000).toISOString().slice(0, 10);
  server.historyDates = { start: day(-2), middle: day(-1), today: day(0), end: day(4) };
  issue = (await owner('POST', '/projects/' + project.id + '/issues', { title: 'Sprint issue', estimate: 5 })).data.issue;
  const created = await owner('POST', '/projects/' + project.id + '/sprints', { name: 'October', goal: 'Deliver', startDate: server.historyDates.start, endDate: server.historyDates.end });
  assert.equal(created.status, 201, JSON.stringify(created.data)); sprint = created.data.sprint;
});
afterEach(async () => { await server.close(); });
const scope = () => owner('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [issue.id] });
test('sprint creation and metadata edit preserve planned state and dates', async () => {
  assert.equal(sprint.status, 'planned');
  const updated = await owner('PATCH', '/sprints/' + sprint.id, { name: 'Delivery', goal: 'Ship the roadmap' });
  assert.equal(updated.data.sprint.name, 'Delivery'); assert.equal(updated.data.sprint.goal, 'Ship the roadmap');
  assert.equal((await owner('GET', '/projects/' + project.id + '/sprints?status=planned')).data.items.length, 1);
});
test('sprint dates reject invalid calendar values and reversed ranges', async () => {
  assert.equal((await owner('PATCH', '/sprints/' + sprint.id, { endDate: '2026-09-30' })).status, 422);
  assert.equal((await owner('PATCH', '/sprints/' + sprint.id, { startDate: '2026-02-30' })).status, 422);
});
test('sprint start permits only one active sprint per project', async () => {
  assert.equal((await owner('POST', '/sprints/' + sprint.id + '/start', {})).data.sprint.status, 'active');
  const other = (await owner('POST', '/projects/' + project.id + '/sprints', { name: 'Next', startDate: '2026-10-08', endDate: '2026-10-14' })).data.sprint;
  assert.equal((await owner('POST', '/sprints/' + other.id + '/start', {})).status, 409);
  assert.equal((await owner('POST', '/sprints/' + sprint.id + '/start', {})).status, 409);
});
test('scope add and remove update point and issue totals with retained history', async () => {
  assert.equal((await scope()).data.sprint.scopePoints, 5);
  assert.equal((await owner('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [issue.id] })).status, 409);
  const removed = await owner('DELETE', '/sprints/' + sprint.id + '/issues/' + issue.id);
  assert.equal(removed.data.sprint.issueCount, 0);
  const history = (await owner('GET', '/sprints/' + sprint.id + '?history=true')).data.issues;
  assert.equal(history[0].active, false); assert(history[0].removedAt);
});
test('scope rejects foreign issues before changing any membership', async () => {
  const other = (await owner('POST', '/orgs/' + org.id + '/projects', { key: 'OT', name: 'Other' })).data.project;
  const foreign = (await owner('POST', '/projects/' + other.id + '/issues', { title: 'Foreign' })).data.issue;
  assert.equal((await owner('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [issue.id, foreign.id] })).status, 422);
  assert.equal((await owner('GET', '/sprints/' + sprint.id)).data.sprint.issueCount, 0);
});
test('daily burndown reflects estimate changes and completion from issue events', async () => {
  await scope(); await owner('POST', '/sprints/' + sprint.id + '/start', {});
  server.ctx.db.prepare("UPDATE sprint_changes SET at=? WHERE sprint_id=? AND kind='added'").run(server.historyDates.start + 'T10:00:00.000Z', sprint.id);
  await owner('PATCH', '/issues/' + issue.id, { estimate: 8 });
  server.ctx.db.prepare("UPDATE sprint_changes SET at=? WHERE sprint_id=? AND kind='issue_changed'").run(server.historyDates.middle + 'T10:00:00.000Z', sprint.id);
  await owner('PATCH', '/issues/' + issue.id, { statusId: project.statuses[2].id });
  const data = (await owner('GET', '/sprints/' + sprint.id + '/burndown')).data;
  assert.deepEqual(data.days.slice(0, 3).map(day => day.remaining), [5, 8, 0]);
  assert.equal(data.days[1].scope, 8); assert.equal(data.days[2].remainingIssues, 0); assert.equal(data.days[3].remaining, null);
});
test('completion snapshots results and carries only unfinished issues to next sprint', async () => {
  const completed = (await owner('POST', '/projects/' + project.id + '/issues', { title: 'Done issue', estimate: 3, statusId: project.statuses[2].id })).data.issue;
  await owner('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [issue.id, completed.id] });
  const next = (await owner('POST', '/projects/' + project.id + '/sprints', { name: 'Next', startDate: '2026-10-08', endDate: '2026-10-14' })).data.sprint;
  await owner('POST', '/sprints/' + sprint.id + '/start', {});
  const result = await owner('POST', '/sprints/' + sprint.id + '/complete', { carryOverSprintId: next.id });
  assert.equal(result.status, 200, JSON.stringify(result.data));
  assert.deepEqual(result.data.result.carriedIssueIds, [issue.id]); assert.deepEqual(result.data.result.completedIssueIds, [completed.id]);
  assert.equal(result.data.carryOverSprint.remainingPoints, 5);
  assert.equal((await owner('POST', '/sprints/' + next.id + '/start', {})).status, 200);
});
test('completed sprint cannot change scope or metadata and keeps frozen totals', async () => {
  await scope(); await owner('POST', '/sprints/' + sprint.id + '/start', {}); await owner('POST', '/sprints/' + sprint.id + '/complete', {});
  await owner('PATCH', '/issues/' + issue.id, { estimate: 13 });
  assert.equal((await owner('GET', '/sprints/' + sprint.id)).data.sprint.scopePoints, 5);
  assert.equal((await owner('PATCH', '/sprints/' + sprint.id, { goal: 'No' })).status, 409);
  assert.equal((await owner('DELETE', '/sprints/' + sprint.id + '/issues/' + issue.id)).status, 409);
});
test('deleting an issue records a scope reduction without losing sprint history', async () => {
  await scope(); await owner('DELETE', '/issues/' + issue.id);
  const result = (await owner('GET', '/sprints/' + sprint.id + '?history=true')).data;
  assert.equal(result.sprint.issueCount, 0); assert.equal(result.issues[0].title, 'Sprint issue'); assert.equal(result.issues[0].issue, null);
  assert(server.ctx.db.prepare("SELECT 1 FROM sprint_changes WHERE sprint_id=? AND kind='issue_deleted'").get(sprint.id));
});
test('guest reads granted sprint and burndown but cannot plan', async () => {
  assert.equal((await guest('GET', '/sprints/' + sprint.id)).status, 200);
  assert.equal((await guest('GET', '/sprints/' + sprint.id + '/burndown')).status, 200);
  assert.equal((await guest('POST', '/sprints/' + sprint.id + '/start', {})).status, 403);
  assert.equal((await guest('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [issue.id] })).status, 403);
});
test('planned sprint deletes cleanly while active sprint deletion is denied', async () => {
  assert.equal((await owner('DELETE', '/sprints/' + sprint.id)).status, 200);
  assert.equal((await owner('GET', '/sprints/' + sprint.id)).status, 404);
});
test('sprint mutation events include organization project and before after state', async () => {
  const events = []; server.ctx.bus.subscribe(event => events.push(event));
  await scope(); const event = events.find(event => event.action === 'scope_added');
  assert.equal(event.orgId, org.id); assert.equal(event.projectId, project.id); assert.equal(event.before.issueCount, 0); assert.equal(event.after.issueCount, 1); assert(event.actorId && event.time);
});
